nextflow_process {

    name "Test Process SAMPLESHEETPARSER_VALIDATE"
    script "../main.nf"
    process "SAMPLESHEETPARSER_VALIDATE"

    tag "samplesheetparser"
    tag "samplesheetparser/validate"
    tag "modules"
    tag "modules_nfcore"

    test("V1 dual-index sheet - validate") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test_v1' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.v1.csv', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("V2 dual-index sheet - validate") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test_v2' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.v2.csv', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("V2 sheet - validate against a custom JSON schema") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test_schema' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.v2.csv', checkIfExists: true)
                ]
                input[1] = Channel.of('{"\$schema":"https://json-schema.org/draft/2020-12/schema","type":"object"}').collectFile(name: 'custom_schema.json')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("V2 sheet - rejected by a custom JSON schema") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test_schema_fail' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.v2.csv', checkIfExists: true)
                ]
                // The sheet projects to a JSON object, so a schema that requires
                // a top-level array must reject it, proving the schema is applied.
                input[1] = Channel.of('{"\$schema":"https://json-schema.org/draft/2020-12/schema","type":"array"}').collectFile(name: 'reject_schema.json')
                """
            }
        }

        then {
            assert process.failed
        }
    }

    test("V1 dual-index sheet - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id: 'test_stub' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.v1.csv', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

